        body: `三角形の3つの内角を全部たすと、どんな形の三角形でも必ず180°になります。これは算数・数学の中でもっとも基本的なきまりの1つです。

■ なぜ180°になるのか
三角形の1つの頂点を通り、対辺に平行な直線を引くと、平行線の性質（錯角・同位角）を使って、3つの角がちょうど1直線（180°）に並ぶことが説明できます。

■ 使い方（2つの角から残り1つを求める）
例）三角形で角B＝55°、角C＝65°のとき、角Aは？
　角A＝180°－55°－65°＝60°

■ 特別な三角形での確認
・正三角形：3つの角がすべて等しいので、1つの角＝180÷3＝60°
・直角二等辺三角形：90°＋45°＋45°＝180°（正しい）
・直角三角形：90°＋残り2角＝180° → 残り2角の和は必ず90°

★ ポイント：「内角の和180°」は形（正三角形・直角三角形・とがった三角形など）に関係なく、いつでも使える最強のルールです。`,
