        body: `■ 頂点を通る平行線を引くと、3 つの角が 1 本の直線に並ぶ
三角形 ABC の頂点 A を通って、辺 BC に平行な直線を引きます。すると、角 B と「A の左側にできる角」は平行線の錯角なので等しく、角 C と「A の右側にできる角」も錯角で等しい。A のまわりには「左の角（＝角 B）」「角 A」「右の角（＝角 C）」が並び、この 3 つは 1 本の直線の上にあるので合わせて 180°。だから**角 A ＋ 角 B ＋ 角 C ＝ 180°**。三角形の形がどうであれ、平行線は必ず引けるので、どんな三角形でも成り立ちます。

■ 紙をちぎって並べると 1 直線になる理由
3 つの角をちぎって 1 点に集めると、上の平行線の説明とまったく同じ配置になります。細長くても、とがっていても、ぴったり 1 直線に並ぶのは、**3 つの角の合計が 180° という直線の角度に等しい**からです。

■ 外角は「となりでない 2 つの内角の和」
角 C の外角は、辺 BC を C の先にのばしてできる角で、内角 C と合わせて 180°（1 直線）です。内角 C ＝ 180−72−48 ＝ 60° なので、外角は 180−60 ＝ 120°。これは角 A ＋ 角 B ＝ 72＋48 ＝ 120° と同じ数です。**外角 ＝ 180 − 内角 ＝（内角の和 180）− 内角 ＝ 残りの 2 つの内角の和**。ひっかけの 60° は内角 C そのもので、外角ではありません。

■ 直角三角形の残り 2 つの角は合わせて 90°
角 A が直角（90°）なら、角 B ＋ 角 C ＝ 180−90 ＝ 90°。角 B ＝ 35° なら角 C ＝ 90−35 ＝ 55°。ひっかけの 145° は 180−35 で、直角の 90° を引き忘れたものです。145° の角があると角 A の 90° と合わせて 235° になり、180° をこえてしまいます。**1 つの三角形に 90° より大きい角は 1 つまで**、直角三角形の残りの角は必ず 90° より小さい、と覚えておくと防げます。

■ 内角の和は「使い方」が 2 つ
①2 つの角から残り 1 つを引き算で出す ②外角を「残り 2 つの内角の和」で出す。どちらも 180° という 1 つの事実から出ていて、四角形の内角の和（360°：対角線で三角形 2 つに分ける）や多角形の内角の和も、この三角形の 180° を土台にしています。

★ ここがポイント：頂点を通る**平行線の錯角**で 3 つの角が 1 直線（180°）に並ぶから、どんな三角形でも内角の和は 180°。**外角 ＝ となりでない 2 つの内角の和**。直角三角形の残り 2 つの角は合わせて 90°。`,
