        body: `■ 各頂点で「外角のぶんだけ向きを変える」
多角形のふちに沿って歩くと、辺の上ではまっすぐ進み、頂点に来るたびに**外角のぶんだけ向きを変えます**（内角ではなく外角。まっすぐ進む向きからどれだけ曲がるかが外角）。1 周して出発点に戻ったとき、体の向きはもとの向きに戻っています。つまり曲がった角度の合計はちょうど 1 回転＝360°。頂点が 3 つでも 100 個でも、**1 周すれば 1 回転**なので、外角の和は辺の数に関係なく 360° です。

■ 内角の和から計算しても 360° になる
各頂点で 内角 ＋ 外角 ＝ 180° なので、n 個の頂点で合計 180n。ここから内角の和 (n−2)×180 ＝ 180n−360 を引くと、外角の和 ＝ 180n−(180n−360) ＝ **360**。n が消えるので、辺の数によらないことが式からも分かります。

■ 1800° がまちがいである理由
ひっかけの 1800° は正十二角形の**内角の和** (12−2)×180 です。外角の和は 360°。「内角の和は辺の数で増える、外角の和は増えない」という 2 つの性質を混ぜると、この取りちがえが起こります。

■ 正 n 角形の 1 つの外角は 360÷n
正多角形は外角がすべて等しいので、360° を n 等分すれば 1 つの外角。正十角形なら 360÷10＝36°。ひっかけの 360° は「和」を「1 つの角」と答えたものです。1 つの外角が 360° なら、その頂点でまっすぐ 1 回転することになり、多角形になりません。

■ へこんだ多角形では成り立たない
この性質は凸多角形（へこみが無い形）のもので、へこんだ頂点では向きを逆に曲げるため、単純な足し算では 360° になりません。中学受験で出るのは凸多角形なので、「凸なら 360°」と覚えておきます。

★ ここがポイント：多角形のふちを 1 周すると**向きがちょうど 1 回転（360°）**するので、外角の和は辺の数に関係なく 360°。式でも 180n − (n−2)×180 ＝ 360 で n が消える。正 n 角形の 1 つの外角は **360÷n**。内角の和と混同しない。`,
