        body: `円の面積は、半径を2回かけてから円周率をかけると求められます。円周の公式（直径×3.14）とは使う長さが違うので注意しましょう。

■ 基本公式
　円の面積＝半径×半径×3.14

例）半径9cmの円の面積は？
　9×9×3.14＝81×3.14＝254.34cm²

■ 直径から半径を求める場合
直径しか与えられていないときは、まず2で割って半径を求めてから公式に入れます。
例）直径10cmの円の面積は？
　半径＝10÷2＝5cm
　面積＝5×5×3.14＝25×3.14＝78.5cm²

■ 覚えておくと便利な値
半径5cm→78.5cm²、半径10cm→314cm²、半径6cm→113.04cm²

⚠ 注意：円周の公式は「直径×3.14」、面積の公式は「半径×半径×3.14」。使う長さの種類（直径か半径か）が違うことをはっきり区別しましょう。`,
