        body: `■ 細かく切って並べかえると長方形になる
円を中心から放射状に細かく切り（ピザのように）、切った三角形のような形を上下交互に並べると、だんだん**長方形に近い形**になります。この長方形のたては円の半径、よこは円周の半分（切った形の弧が上下に半分ずつ並ぶから）です。円周は 直径×3.14＝半径×2×3.14 なので、その半分は 半径×3.14。長方形の面積 ＝ たて × よこ ＝ 半径 × (半径×3.14) ＝ **半径 × 半径 × 3.14**。切り方を細かくするほど本当の長方形に近づくので、この式が円の面積です。

■ 「半径 × 半径」は正方形の何個ぶんか
半径×半径 は「半径を 1 辺とする正方形」の面積です。円の面積はその 3.14 倍——円の中に、半径の正方形が 3 個と少し入る、と読めます。半径 9cm なら正方形 81cm² が 3.14 個ぶんで 254.34cm²。**面積は「1cm の正方形が何個か」**なので、半径を 2 回かけて cm² を作り、それを 3.14 倍しています。

■ 314cm² がまちがいである理由
ひっかけの 314cm² は 10×10×3.14 で、直径 10cm をそのまま半径として使ったものです。面積の公式の「半径」に直径を入れると、半径 2 倍 → 面積は 4 倍（2×2）になります。正しくは半径 5cm で 5×5×3.14＝78.5cm²。**面積は半径を 2 回かけるので、半径を取りちがえると 4 倍ずれる**。

■ 37.68cm² がまちがいである理由
ひっかけの 37.68cm² は 6×2×3.14 で、円周の公式を使ったものです。長さの公式で面積は出ません。正しくは 6×6×3.14＝113.04cm²。円周（直径×3.14）と面積（半径×半径×3.14）は、**3.14 をかける点は同じでも、前に来る長さがちがう**——円周は直径 1 つ、面積は半径 2 つ。

■ 覚えておく値の使い方
半径 5 → 78.5、半径 10 → 314、半径 6 → 113.04。3.14 の段（×25、×100、×36）をそのまま覚えたもので、おうぎ形や複合図形の問題でも出てくるので、暗記しておくと速い。

★ ここがポイント：円を細かく切って並べると**たて ＝ 半径、よこ ＝ 円周の半分（半径×3.14）の長方形**になるので、面積 ＝ **半径 × 半径 × 3.14**。直径を入れると 4 倍ずれる。円周は直径 1 つ、面積は半径 2 つ。`,
