        body: `■ 同じ三角形を 2 つ合わせると平行四辺形
三角形をもう 1 つ用意して、逆さまにしてくっつけると平行四辺形になります。平行四辺形の面積は 底辺 × 高さ（切って動かせば長方形になる）で、これは三角形 2 つぶん。だから三角形 1 つは **底辺 × 高さ ÷ 2**。÷ 2 は「2 つに増やしたぶんを 1 つに戻す」操作です。底辺 8cm・高さ 5cm なら 8×5＝40cm² が平行四辺形、その半分 20cm² が三角形。

■ 40cm² がまちがいである理由
ひっかけの 40cm² は底辺 × 高さ で止めたもので、平行四辺形の面積です。三角形は平行四辺形の半分なので、÷ 2 を忘れると 2 倍になります。**「三角形」と見たら ÷ 2** を、式を書く前と答えを書く前の 2 回確かめます。

■ 高さは「底辺に垂直な長さ」
高さは、底辺に対して直角に測った長さで、底辺の向かいの頂点から底辺（またはその延長）へ下ろした垂線の長さです。斜めの辺の長さを高さにすると、面積が大きく出ます。斜めの辺は垂線より必ず長いからです。図に垂線を書きこみ、直角の印をつけてから高さを読みます。

■ 逆算：面積から高さ
面積 24cm²・底辺 6cm なら、底辺 × 高さ ＝ 24×2 ＝ 48（平行四辺形に戻す）、高さ ＝ 48÷6 ＝ 8cm。ひっかけの 4cm は 24÷6 で、÷ 2 の逆（× 2）を忘れたものです。**面積から戻すときは、まず 2 倍して平行四辺形にしてから底辺でわる**。4cm を高さとして確かめると 6×4÷2＝12cm² で 24 になりません。

■ どの辺を底辺にしても同じ
三角形は 3 つの辺のどれを底辺にしてもよく、そのときの高さは変わりますが、底辺 × 高さ ÷ 2 の答えは同じです。問題で「高さ」が与えられていたら、**その高さが垂直に立っている辺**が底辺です。

★ ここがポイント：三角形 2 つで平行四辺形（底辺 × 高さ）になるので、三角形は **底辺 × 高さ ÷ 2**。高さは底辺に**垂直**な長さで、斜めの辺ではない。面積から高さを戻すときは **2 倍してから底辺でわる**。`,
