        body: `■ はしを切って動かすと長方形になる
平行四辺形の左はし（または右はし）の直角三角形を切り取り、反対側にくっつけると、同じ底辺・同じ高さの長方形になります。切って動かしても面積は変わらない（等積変形）ので、平行四辺形の面積 ＝ 長方形の面積 ＝ **底辺 × 高さ**。三角形のときとちがって、2 つに増やしていないので ÷ 2 は要りません。

■ 斜辺は「たて」ではない
長方形に直したとき、たての長さになるのは**底辺に垂直な高さ**であって、斜めの辺（斜辺）ではありません。底辺 6cm・斜辺 5cm・高さ 4cm の平行四辺形なら、面積は 6×4＝24cm²。ひっかけの 30cm² は 6×5 で、斜辺を高さにしたものです。斜辺は垂線より必ず長いので（5 ＞ 4）、斜辺を使うと面積が大きく出ます。平行四辺形をどんどんつぶしていくと、斜辺の長さは変わらないのに高さは 0 に近づき面積も 0 に近づく——**面積を決めるのは高さであって斜辺ではない**ことが、この「つぶす」イメージで分かります。

■ 14cm² がまちがいである理由
底辺 7cm・高さ 4cm で 14cm² は、7×4÷2 と三角形の公式を使ったものです。平行四辺形は長方形に変形できるので ÷ 2 はありません。正しくは 28cm²。**÷ 2 は「三角形」「台形」のときだけ**（2 つ合わせて平行四辺形にする図形）。

■ どの辺を底辺にしてもよい
平行四辺形は向かい合う辺が平行なので、どの辺を底辺にしても、対応する高さを使えば同じ面積になります。底辺 6cm・高さ 4cm で 24cm² なら、斜辺 5cm を底辺にしたときの高さは 24÷5＝4.8cm。**底辺を変えると高さも変わる**ので、問題で与えられた高さがどの辺に垂直かを確かめます。

■ 三角形の公式との関係
三角形は「2 つで平行四辺形」なので 底辺 × 高さ ÷ 2。平行四辺形は「はしを動かして長方形」なので 底辺 × 高さ。**÷ 2 があるかないかの理由**を、この 2 つの変形で覚えておきます。

★ ここがポイント：平行四辺形は**はしの三角形を動かすと長方形**になるので、面積 ＝ **底辺 × 高さ**（÷ 2 なし）。高さは底辺に**垂直**な長さで、斜辺ではない（つぶすと斜辺は同じでも面積は減る）。底辺を変えれば対応する高さも変わる。`,
