        body: `■ 三角形の角は 2 つ決まれば 3 つ目も決まる
三角形の内角の和は 180° なので、2 つの角が分かれば残りの角は 180 から引いて決まります。だから「2 組の角が等しい」なら、実は**3 組の角がすべて等しい**。角がすべて等しい三角形は、拡大・縮小しただけの同じ形（相似）です。角度の情報だけで相似が言えるので、入試ではこの条件がいちばん多く使われます。

■ 辺の比だけ、角だけでは足りない場合
2 組の辺の比が等しくても、**その 2 辺にはさまれた角**が等しくなければ相似とは言えません。はさまれていない角が等しい場合、同じ 2 辺と角で形のちがう三角形が 2 通り作れることがあるからです（ひっかけ①の「言えない」）。逆に 3 組の辺の比がすべて等しければ、三角形の形は 1 つに決まるので相似です。

■ 長方形は角が同じでも相似とは限らない
2 つの長方形は 4 つの角がどれも 90° で等しいのに、たて 1・よこ 5 の細長い長方形と、たて 1・よこ 1 の正方形は明らかに形がちがいます。**四角形は角がすべて等しくても、辺の比がちがえば形がちがう**（三角形は角で形が決まるが、四角形は決まらない）。だから相似の定義は「対応する角がすべて等しく、かつ対応する辺の比がすべて等しい」の両方で、三角形だけは角の条件から辺の条件が自動的に成り立ちます。

■ 相似の性質と使い方
相似なら、対応する辺の比はどこを取っても同じ（AB:A′B′ ＝ BC:B′C′ ＝ CA:C′A′）。この「どこを取っても同じ比」を使って、測っていない辺の長さを求めるのが次の単元です。対応する頂点を、等しい角どうしで結びつけてから比を作ります。

■ 合同との関係
合同は相似比 1:1 の相似。「形も大きさも同じ」が合同、「形だけ同じ」が相似です。

★ ここがポイント：三角形は**2 組の角が等しければ 3 組目も等しくなる**（内角の和 180°）ので、角だけで相似が決まる。辺の比を使うなら**はさまれた角**が必要、または 3 組の辺の比。四角形は角が等しくても相似とは限らない（辺の比も必要）。`,
